namespace ghidra.graph.viewer.layout;



/**
 * A listener for layout changes.
 *
 * @param <V> the vertex type
 * @param <E> the edge type
 */
public interface LayoutListener<V, E> {

	public class ChangeType
{	public static readonly ChangeType API = new();
	public static readonly ChangeType TRANSIENT = new();
	public static readonly ChangeType RESTORE = new();
	public static readonly ChangeType USER = new();
			// user initiated change, such as the user dragging a vertex

		public bool isTransitional() {
			return this == RESTORE || this == TRANSIENT;
		}
	}

	/**
	 * Called when a vertex location has changed.
	 * 
	 * @param v the vertex
	 * @param point the new vertex location
	 * @param changeType the type of the change
	 */
	public void vertexLocationChanged(V v, Point2D point, ChangeType changeType);
}
